import React from 'react';
import img4693 from '../images/IMG_4693.JPG';
import Avatar from '@mui/material/Avatar';
import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';

function Home() {
  return (
    <div style={{ backgroundColor: '#012340', display: 'flex', height: '100vh' }}>
      <div style={{ width: '50%', border: '1px solid black', padding: '20px' }}>
        <List>
          <ListItem>Experience One</ListItem>
          <ListItem>Experience Two</ListItem>
          <ListItem>Experience Three</ListItem>
          <ListItem>Experience Four</ListItem>
        </List>
      </div>
      <div style={{ width: '50%', border: '1px solid black', padding: '20px',display: 'flex', textAlign: 'center', justifyContent: 'center', alignItems: 'center' }}>

        <Avatar src={img4693} alt='Paulo Santos' sx={{ width: 100, height: 100 }} />
        <p style={{ marginTop: '10px' }}>Home</p>
      </div>
    </div>
  );
}

export default Home;
